import{_ as o,C as d,o as r,c as i,ae as e,E as n}from"./chunks/framework.Co1PSFSm.js";const f=JSON.parse('{"title":"Tab Item (v1.0.0)","description":"","frontmatter":{"title":"Tab Item (v1.0.0)"},"headers":[],"relativePath":"v1.0.0/components/tab-item.md","filePath":"v1.0.0/components/tab-item.md"}'),l={name:"v1.0.0/components/tab-item.md"};function s(p,t,c,b,h,x){const a=d("TabItemPlayground");return r(),i("div",null,[t[0]||(t[0]=e('<div class="warning custom-block"><p class="custom-block-title">You are viewing the archived v1.0.0 documentation.</p><p><a href="/components/tab-item.html">View the latest version →</a></p></div><h1 id="tab-item" tabindex="-1">Tab Item <a class="header-anchor" href="#tab-item" aria-label="Permalink to &quot;Tab Item&quot;">​</a></h1><p>A single tab within a Tab Bar. Represents one view or document the user can switch to. Width is hug (content-driven) with a hard <strong>320px maximum</strong> — labels beyond that are truncated with an ellipsis (…). Height is always <strong>48px</strong>.</p><hr><h2 id="playground" tabindex="-1">Playground <a class="header-anchor" href="#playground" aria-label="Permalink to &quot;Playground&quot;">​</a></h2><p>Try all variants and states interactively. The spec readout at the bottom updates live.</p>',6)),n(a),t[1]||(t[1]=e('<hr><h2 id="anatomy" tabindex="-1">Anatomy <a class="header-anchor" href="#anatomy" aria-label="Permalink to &quot;Anatomy&quot;">​</a></h2><div style="background:#f6f8fa;border:1px solid #e2e8f0;border-radius:12px;padding:32px 24px;margin:24px 0;font-family:sans-serif;"><div style="display:inline-flex;border-bottom:4px solid #000;height:48px;align-items:center;padding:0 16px;gap:8px;background:#fff;border-radius:4px 4px 0 0;border:1px solid #e2e8f0;"><div style="width:16px;height:16px;border-radius:4px;background:rgb(215,25,47);border:1px solid rgb(230,230,230);flex-shrink:0;"></div><span style="font-size:12px;color:#000;border:1px solid currentColor;border-radius:50%;width:14px;height:14px;display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;font-weight:700;">i</span><span style="font-size:13px;font-weight:700;color:rgb(0,0,0);">Tab label</span><span style="font-size:11px;color:rgb(0,0,0);">✕</span></div><div style="margin-top:28px;display:grid;grid-template-columns:1fr 1fr;gap:14px;font-size:13px;color:#475569;"><div style="display:flex;align-items:flex-start;gap:8px;"><span style="background:#6366f1;color:#fff;border-radius:50%;width:20px;height:20px;display:inline-flex;align-items:center;justify-content:center;font-size:11px;flex-shrink:0;">1</span><div><strong>Swatch</strong><br>16×16px color dot, radius 4px. Identifies a job or document by color. Mutually exclusive with Icon.</div></div><div style="display:flex;align-items:flex-start;gap:8px;"><span style="background:#6366f1;color:#fff;border-radius:50%;width:20px;height:20px;display:inline-flex;align-items:center;justify-content:center;font-size:11px;flex-shrink:0;">2</span><div><strong>Icon</strong><br>14×14px Outline icon only. Communicates content category (info, warning, etc.). Mutually exclusive with Swatch.</div></div><div style="display:flex;align-items:flex-start;gap:8px;"><span style="background:#6366f1;color:#fff;border-radius:50%;width:20px;height:20px;display:inline-flex;align-items:center;justify-content:center;font-size:11px;flex-shrink:0;">3</span><div><strong>Label</strong><br>Roboto Bold, 13px / 21px. Truncated with ellipsis when total tab width exceeds 320px.</div></div><div style="display:flex;align-items:flex-start;gap:8px;"><span style="background:#6366f1;color:#fff;border-radius:50%;width:20px;height:20px;display:inline-flex;align-items:center;justify-content:center;font-size:11px;flex-shrink:0;">4</span><div><strong>Close ×</strong><br>14×14px. Removes the tab. Hidden on pinned tabs or when only one tab is open.</div></div><div style="display:flex;align-items:flex-start;gap:8px;"><span style="background:#6366f1;color:#fff;border-radius:50%;width:20px;height:20px;display:inline-flex;align-items:center;justify-content:center;font-size:11px;flex-shrink:0;">5</span><div><strong>Active indicator</strong><br>4px bottom border in <code>color/black/100</code>. Visible only on the currently active tab.</div></div></div></div><hr><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Values</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>State</code></td><td>Default · Hover · Active · Disabled</td><td>Default</td><td>Visual interaction state</td></tr><tr><td><code>Label</code></td><td>string</td><td>&quot;Tab label&quot;</td><td>Editable text; truncated at 320px total width</td></tr><tr><td><code>Show Swatch</code></td><td>true · false</td><td>true</td><td>Shows a 16×16px color dot</td></tr><tr><td><code>Swatch Color</code></td><td>RGB</td><td><code>rgb(215, 25, 47)</code></td><td>Color of the swatch in <code>rgb(r, g, b)</code> format only</td></tr><tr><td><code>Show Icon</code></td><td>true · false</td><td>true</td><td>Shows a 14×14px Outline icon</td></tr><tr><td><code>Show Close</code></td><td>true · false</td><td>true</td><td>Shows the × close button</td></tr></tbody></table><blockquote><p>⚠ <code>Show Swatch</code> and <code>Show Icon</code> are mutually exclusive. Never enable both at the same time.</p></blockquote><hr><h2 id="content-variants" tabindex="-1">Content Variants <a class="header-anchor" href="#content-variants" aria-label="Permalink to &quot;Content Variants&quot;">​</a></h2><p>Four official variants. Optional slots (Swatch, Icon, Close) collapse automatically when hidden.</p><h3 id="_1-·-label-only" tabindex="-1">1 · Label only <a class="header-anchor" href="#_1-·-label-only" aria-label="Permalink to &quot;1 · Label only&quot;">​</a></h3><p>Simple navigation tab. No color identity or category. Use for fixed views.</p><div style="font-family:sans-serif;margin:12px 0 20px;"><div style="display:inline-flex;border-bottom:4px solid transparent;height:48px;align-items:center;padding:0 16px;gap:8px;border:1px solid #e2e8f0;border-radius:4px 4px 0 0;"><span style="font-size:13px;font-weight:700;color:rgb(0,0,0);">Overview</span></div></div><h3 id="_2-·-swatch-label" tabindex="-1">2 · Swatch + Label <a class="header-anchor" href="#_2-·-swatch-label" aria-label="Permalink to &quot;2 · Swatch + Label&quot;">​</a></h3><p>Color dot paired with a label. Use when the tab represents a job or document with a unique color identity.</p><div style="font-family:sans-serif;margin:12px 0 20px;"><div style="display:inline-flex;border-bottom:4px solid transparent;height:48px;align-items:center;padding:0 16px;gap:8px;border:1px solid #e2e8f0;border-radius:4px 4px 0 0;"><div style="width:16px;height:16px;border-radius:4px;background:rgb(215,25,47);border:1px solid rgb(230,230,230);flex-shrink:0;"></div><span style="font-size:13px;font-weight:700;color:rgb(0,0,0);">Job A — Fabric inspection</span></div></div><h3 id="_3-·-swatch-label-close-most-common" tabindex="-1">3 · Swatch + Label + Close <em>(most common)</em> <a class="header-anchor" href="#_3-·-swatch-label-close-most-common" aria-label="Permalink to &quot;3 · Swatch + Label + Close _(most common)_&quot;">​</a></h3><p>Closeable job or document tab. The most frequently used variant in the product.</p><div style="font-family:sans-serif;margin:12px 0 20px;"><div style="display:inline-flex;border-bottom:4px solid rgb(0,0,0);height:48px;align-items:center;padding:0 16px;gap:8px;border:1px solid #e2e8f0;border-radius:4px 4px 0 0;"><div style="width:16px;height:16px;border-radius:4px;background:rgb(215,25,47);border:1px solid rgb(230,230,230);flex-shrink:0;"></div><span style="font-size:13px;font-weight:700;color:rgb(0,0,0);">Job A — Fabric inspection</span><span style="font-size:11px;color:rgb(0,0,0);cursor:pointer;">✕</span></div></div><h3 id="_4-·-icon-label-close" tabindex="-1">4 · Icon + Label + Close <a class="header-anchor" href="#_4-·-icon-label-close" aria-label="Permalink to &quot;4 · Icon + Label + Close&quot;">​</a></h3><p>Categorized, closeable tab. Use when the content type has semantic meaning (info, warning, error) that an icon can communicate.</p><div style="font-family:sans-serif;margin:12px 0 20px;"><div style="display:inline-flex;border-bottom:4px solid transparent;height:48px;align-items:center;padding:0 16px;gap:8px;border:1px solid #e2e8f0;border-radius:4px 4px 0 0;"><span style="font-size:12px;color:rgb(0,0,0);border:1px solid currentColor;border-radius:50%;width:14px;height:14px;display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;font-weight:700;">i</span><span style="font-size:13px;font-weight:700;color:rgb(0,0,0);">Calibration report</span><span style="font-size:11px;color:rgb(0,0,0);cursor:pointer;">✕</span></div></div><hr><h2 id="states" tabindex="-1">States <a class="header-anchor" href="#states" aria-label="Permalink to &quot;States&quot;">​</a></h2><h3 id="default" tabindex="-1">Default <a class="header-anchor" href="#default" aria-label="Permalink to &quot;Default&quot;">​</a></h3><p>Base state. Label uses <code>color/text/tertiary</code>. No background, no border indicator.</p><div style="font-family:sans-serif;margin:12px 0 20px;background:#f6f8fa;border:1px solid #e2e8f0;border-radius:8px;padding:20px;"><div style="display:inline-flex;border-bottom:4px solid transparent;height:48px;align-items:center;padding:0 16px;gap:8px;"><div style="width:16px;height:16px;border-radius:4px;background:rgb(215,25,47);border:1px solid rgb(230,230,230);flex-shrink:0;"></div><span style="font-size:13px;font-weight:700;color:rgb(151,153,155);white-space:nowrap;">Tab label</span><span style="font-size:11px;color:rgb(151,153,155);">✕</span></div></div><h3 id="hover" tabindex="-1">Hover <a class="header-anchor" href="#hover" aria-label="Permalink to &quot;Hover&quot;">​</a></h3><p>Triggered on pointer over. Background becomes <code>rgba(0,0,0,0.04)</code>. Label color stays tertiary.</p><div style="font-family:sans-serif;margin:12px 0 20px;background:#f6f8fa;border:1px solid #e2e8f0;border-radius:8px;padding:20px;"><div style="display:inline-flex;border-bottom:4px solid transparent;height:48px;align-items:center;padding:0 16px;gap:8px;background:rgba(0,0,0,0.04);"><div style="width:16px;height:16px;border-radius:4px;background:rgb(215,25,47);border:1px solid rgb(230,230,230);flex-shrink:0;"></div><span style="font-size:13px;font-weight:700;color:rgb(151,153,155);white-space:nowrap;">Tab label</span><span style="font-size:11px;color:rgb(151,153,155);">✕</span></div></div><h3 id="active" tabindex="-1">Active <a class="header-anchor" href="#active" aria-label="Permalink to &quot;Active&quot;">​</a></h3><p>Currently selected tab. Label switches to <code>color/text/primary</code>. A 4px bottom border in <code>color/black/100</code> marks the active position. <strong>Only one tab can be Active at a time.</strong></p><div style="font-family:sans-serif;margin:12px 0 20px;background:#f6f8fa;border:1px solid #e2e8f0;border-radius:8px;padding:20px;"><div style="display:inline-flex;border-bottom:4px solid rgb(0,0,0);height:48px;align-items:center;padding:0 16px;gap:8px;"><div style="width:16px;height:16px;border-radius:4px;background:rgb(215,25,47);border:1px solid rgb(230,230,230);flex-shrink:0;"></div><span style="font-size:13px;font-weight:700;color:rgb(0,0,0);white-space:nowrap;">Tab label</span><span style="font-size:11px;color:rgb(0,0,0);">✕</span></div></div><h3 id="disabled" tabindex="-1">Disabled <a class="header-anchor" href="#disabled" aria-label="Permalink to &quot;Disabled&quot;">​</a></h3><p>Not interactive. The entire tab item is rendered at 40% opacity. Cannot be clicked or focused.</p><div style="font-family:sans-serif;margin:12px 0 20px;background:#f6f8fa;border:1px solid #e2e8f0;border-radius:8px;padding:20px;"><div style="display:inline-flex;border-bottom:4px solid transparent;height:48px;align-items:center;padding:0 16px;gap:8px;opacity:0.4;pointer-events:none;"><div style="width:16px;height:16px;border-radius:4px;background:rgb(215,25,47);border:1px solid rgb(230,230,230);flex-shrink:0;"></div><span style="font-size:13px;font-weight:700;color:rgb(151,153,155);white-space:nowrap;">Tab label</span><span style="font-size:11px;color:rgb(151,153,155);">✕</span></div></div><h3 id="state-summary" tabindex="-1">State summary <a class="header-anchor" href="#state-summary" aria-label="Permalink to &quot;State summary&quot;">​</a></h3><table tabindex="0"><thead><tr><th>State</th><th>Background</th><th>Label color</th><th>Border-bottom</th><th>Interaction</th></tr></thead><tbody><tr><td>Default</td><td>Transparent</td><td><code>color/text/tertiary</code></td><td>None</td><td>Clickable</td></tr><tr><td>Hover</td><td><code>rgba(0,0,0,0.04)</code></td><td><code>color/text/tertiary</code></td><td>None</td><td>Clickable</td></tr><tr><td>Active</td><td>Transparent</td><td><code>color/text/primary</code></td><td>4px <code>color/black/100</code></td><td>Current view</td></tr><tr><td>Disabled</td><td>Transparent, opacity 0.4</td><td><code>color/text/tertiary</code></td><td>None</td><td>Not interactive</td></tr></tbody></table><hr><h2 id="sizing-spacing" tabindex="-1">Sizing &amp; Spacing <a class="header-anchor" href="#sizing-spacing" aria-label="Permalink to &quot;Sizing &amp; Spacing&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Value</th><th>Token</th></tr></thead><tbody><tr><td>Height</td><td>48px</td><td><code>spacing/12</code></td></tr><tr><td>Max width</td><td>320px</td><td>—</td></tr><tr><td>Horizontal padding</td><td>16px</td><td><code>spacing/4</code></td></tr><tr><td>Gap between elements</td><td>8px</td><td><code>spacing/2</code></td></tr><tr><td>Gap in Disabled state</td><td>8px</td><td><code>radius/md</code></td></tr><tr><td>Swatch size</td><td>16×16px</td><td>—</td></tr><tr><td>Swatch border radius</td><td>4px</td><td>—</td></tr><tr><td>Icon size</td><td>14×14px</td><td>—</td></tr><tr><td>Close button size</td><td>14×14px</td><td>—</td></tr><tr><td>Active indicator height</td><td>4px</td><td>—</td></tr></tbody></table><hr><h2 id="typography" tabindex="-1">Typography <a class="header-anchor" href="#typography" aria-label="Permalink to &quot;Typography&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td>Font</td><td>Roboto Bold</td></tr><tr><td>Font size</td><td>13px</td></tr><tr><td>Line height</td><td>21px</td></tr><tr><td>Font variation</td><td><code>wdth 100</code></td></tr><tr><td>Overflow</td><td>Ellipsis (…)</td></tr></tbody></table><hr><h2 id="design-tokens" tabindex="-1">Design Tokens <a class="header-anchor" href="#design-tokens" aria-label="Permalink to &quot;Design Tokens&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Token</th><th>Value</th><th>Usage</th></tr></thead><tbody><tr><td><code>color/brand/200</code></td><td><code>rgb(215, 25, 47)</code></td><td>Default swatch color</td></tr><tr><td><code>color/border/default</code></td><td><code>rgb(230, 230, 230)</code></td><td>Swatch border</td></tr><tr><td><code>color/text/primary</code></td><td><code>rgb(0, 0, 0)</code></td><td>Active label</td></tr><tr><td><code>color/text/tertiary</code></td><td><code>rgb(151, 153, 155)</code></td><td>Default / Hover / Disabled label</td></tr><tr><td><code>color/black/100</code></td><td><code>rgb(0, 0, 0)</code></td><td>Active border-bottom indicator</td></tr><tr><td><code>color/icon/primary</code></td><td><code>rgb(0, 0, 0)</code></td><td>Icon color</td></tr><tr><td><code>spacing/2</code></td><td><code>8px</code></td><td>Element gap</td></tr><tr><td><code>spacing/4</code></td><td><code>16px</code></td><td>Horizontal padding</td></tr><tr><td><code>spacing/12</code></td><td><code>48px</code></td><td>Tab height</td></tr><tr><td><code>radius/md</code></td><td><code>8px</code></td><td>Gap value in Disabled state</td></tr></tbody></table><blockquote><p>Swatch color must always be in <strong>RGB format</strong> — <code>rgb(r, g, b)</code> with values 0–255. Never use hex or HSL.</p></blockquote><hr><h2 id="usage-guidelines" tabindex="-1">Usage guidelines <a class="header-anchor" href="#usage-guidelines" aria-label="Permalink to &quot;Usage guidelines&quot;">​</a></h2><div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:24px 0;font-family:sans-serif;font-size:14px;"><div style="background:#f0fdf4;border:1px solid #bbf7d0;border-radius:8px;padding:16px;"><p style="font-weight:700;color:#15803d;margin:0 0 8px;">✓ Do</p><ul style="margin:0;padding-left:16px;color:#166534;line-height:1.7;"><li>Use one of the 4 official content variants</li><li>Keep only one tab Active per Tab Bar</li><li>Express swatch color as <code>rgb(r, g, b)</code></li><li>Abbreviate long labels — the 320px cap is fixed</li><li>Hide Close on pinned tabs or when it&#39;s the only tab open</li></ul></div><div style="background:#fef2f2;border:1px solid #fecaca;border-radius:8px;padding:16px;"><p style="font-weight:700;color:#b91c1c;margin:0 0 8px;">✕ Don&#39;t</p><ul style="margin:0;padding-left:16px;color:#991b1b;line-height:1.7;"><li>Combine Swatch + Icon in the same tab</li><li>Exceed 320px width or 48px height</li><li>Use hex or HSL for swatch color — only RGB</li><li>Use Filled icons — only Outline 14×14</li><li>Change the color of the Active border-bottom</li></ul></div></div><hr><h2 id="accessibility-notes-for-designers" tabindex="-1">Accessibility notes <em>(for designers)</em> <a class="header-anchor" href="#accessibility-notes-for-designers" aria-label="Permalink to &quot;Accessibility notes _(for designers)_&quot;">​</a></h2><ul><li>The entire header row is the click target — not just the label text</li><li>Active state is communicated by both the bottom border (shape) and label color — not color alone</li><li>Disabled tabs must not be reachable by keyboard and must not show a hover state</li><li>The Close button needs a visible focus ring; its accessible name should read &quot;Close [tab label]&quot;</li><li>Truncated labels must expose the full text in a tooltip on hover</li></ul>',54))])}const u=o(l,[["render",s]]);export{f as __pageData,u as default};
